test("Gmail read-only adapter accepts Gmail DKIM header.i, sends bearer token and decodes MIME HTML",async()=>{let auth;const payload={id:"m",threadId:"t",internalDate:"1760000000000",payload:{headers:[{name:"From",value:"jobs-noreply@indeed.com"},{name:"Subject",value:"New jobs alert"},{name:"Authentication-Results",value:"mx.google.com; dkim=pass header.i=@mail.indeed.com header.s=mail header.b=abc; spf=pass"}],parts:[{mimeType:"text/html",body:{data:btoa("<a href='https://indeed.com/viewjob?jk=1'>Role</a>").replace(/=/g,"")}}]}};const g=new GmailReadOnlyAdapter({getAccessToken:async()=>"secret",fetchImpl:async(u,o)=>{auth=o.headers.authorization;return new Response(JSON.stringify(payload),{status:200})}});const m=await g.getMessage("m");assert.equal(auth,"Bearer secret");assert.equal(m.source,"indeed");assert.match(m.html,/viewjob/);assert.equal(m.is_verified_job_alert,true);assert.equal(m.verification_reason_code,"verified_provider_alert")});
test("fresh Gmail query includes archived alerts, excludes spam and trash, freezes both bounds, and uses catchup sender parity",async()=>{const queries=[];const g=new GmailReadOnlyAdapter({getAccessToken:async()=>"token",fetchImpl:async u=>{queries.push(new URL(u));return Response.json({messages:[]})}});await g.listMessages({maxResults:99,afterEpoch:123,beforeEpoch:456});await g.listMessages({maxResults:100,fullInbox:true});assert.equal(queries[0].searchParams.get("maxResults"),"5");const fresh=queries[0].searchParams.get("q"),catchup=queries[1].searchParams.get("q");assert.match(fresh,/^-in:spam -in:trash after:123 before:456/);assert.doesNotMatch(fresh,/in:inbox/);assert.match(catchup,/^in:inbox/);for(const sender of AUDITED_ALERT_SENDERS){assert.match(fresh,new RegExp(`from:${sender.replaceAll(".","\\.")}`));assert.match(catchup,new RegExp(`from:${sender.replaceAll(".","\\.")}`))}assert.doesNotMatch(fresh,/from:\(linkedin\.com\)/)});
test("Gmail errors expose only allowlisted reason and normalized Retry-After",async()=>{const limited=new GmailReadOnlyAdapter({getAccessToken:async()=>"token",fetchImpl:async()=>new Response(JSON.stringify({error:{message:"private provider text",errors:[{reason:"userRateLimitExceeded"}]}}),{status:403,headers:{"content-type":"application/json","retry-after":"120"}})});await assert.rejects(()=>limited.profile(),error=>{assert.equal(error.message,"gmail_read_403:userRateLimitExceeded:retry_after_seconds_120");assert.doesNotMatch(error.message,/private provider text/);return true});const unknown=new GmailReadOnlyAdapter({getAccessToken:async()=>"token",fetchImpl:async()=>new Response(JSON.stringify({error:{errors:[{reason:"attacker_controlled_reason"}],message:"secret"}}),{status:403,headers:{"retry-after":"not-a-date"}})});await assert.rejects(()=>unknown.profile(),/gmail_read_403:unknown:retry_after_absent/)});
