test("assessment endpoint rejects nonexistent Arsenal and mismatched profile provenance",async()=>{const repo=createMemoryRepo(),env={DASHBOARD_PASSWORD:"test-only",TEST_MODE:"true",TEST_REPOSITORY:repo},login=await worker.fetch(new Request("https://app.test/api/login",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({password:"test-only"})}),env),cookie=login.headers.get("set-cookie").split(";")[0],headers={cookie,"content-type":"application/json"};await repo.saveArsenalIndex({version:"known",source_file_id:ARSENAL_MASTER_FILE_ID,content_hash:"hash",claims:[]});const strict=await repo.saveProfile({id:"strict",...DEFAULT_PROFILE,review_threshold:90}),permissive=await repo.saveProfile({id:"permissive",...DEFAULT_PROFILE,review_threshold:10});repo.state.jobs.set("job",{listing:{title:"Chief Architect",full_description:"enterprise architecture"},evidence:[]});const call=body=>worker.fetch(new Request("https://app.test/api/assess",{method:"POST",headers,body:JSON.stringify(body)}),env);const missingArsenal=await call({job_id:"job",profile_id:"strict",profile_version:strict.version,arsenal_version:"missing"});assert.equal(missingArsenal.status,500);assert.equal((await missingArsenal.json()).error,"arsenal_version_not_found");const mismatched=await call({job_id:"job",profile_id:"strict",profile_version:permissive.version+1,arsenal_version:"known"});assert.equal(mismatched.status,500);assert.equal((await mismatched.json()).error,"profile_version_not_found");const valid=await (await call({job_id:"job",profile_id:"permissive",profile_version:permissive.version,arsenal_version:"known"})).json();assert.equal(valid.profile_id,"permissive");assert.equal(valid.profile_version,permissive.version);assert.equal(repo.state.assessments.length,1)});
