test("D1 discovery checkpoints and completion batch children with parent state atomically",async()=>{const batches=[],db={prepare(sql){return{bind(...args){return{sql,args,first:async()=>({n:1}),run:async()=>({})}}}},batch:async statements=>{batches.push(statements)}},repo=new D1Repository(db),task={id:"parent",observation_id:"mail:0",source:"indeed"},found=[{url:"https://indeed.com/viewjob?jk=abc",classification:"listing"}];await repo.checkpointDiscovery(task,{status:"incomplete_retry",error_code:"bounded",next_url:"https://indeed.com/jobs?q=cio&page=2",pages:1,discovered_tasks:found,seen_urls:[]});assert.equal(batches.length,1);const checkpointSql=batches[0].map(x=>x.sql).join("\n");assert.match(checkpointSql,/parent_task_id/);assert.match(checkpointSql,/INSERT INTO research_checkpoints/);assert.match(checkpointSql,/UPDATE research_tasks SET status=/);batches.length=0;await repo.commitDiscovery(task,found);assert.equal(batches.length,1);const completionSql=batches[0].map(x=>x.sql).join("\n");assert.match(completionSql,/DELETE FROM research_checkpoints/);assert.match(completionSql,/status='complete'/)});

test("package review CAS is revision fenced and conflicts fail closed",async()=>{const sqls=[],db={prepare(sql){sqls.push(sql);return{bind(...args){return{sql,args,first:async()=>sql.startsWith("SELECT status,canonical_job_id,listing_version_id,revision")?{status:"writer_draft",canonical_job_id:"job",listing_version_id:"lv1",revision:4}:sql.startsWith("SELECT status,revision")?{status:"critic_review",revision:5}:null,run:async()=>({})}}}},batch:async statements=>{const update=statements.find(x=>x.sql.startsWith("UPDATE application_packages SET status="));assert.match(update.sql,/AND status=\? AND revision=\?/);assert.deepEqual(update.args.slice(-2),["writer_draft",4]);assert.ok(statements.some(x=>x.sql.includes("package_revision")))}};const repo=new D1Repository(db),result=await repo.reviewPackageCAS("package",{reviewer_role:"writer",decision:"approve",expected_revision:4});assert.equal(result.package_revision,5);assert.ok(sqls.some(x=>x.includes("revision")));await assert.rejects(()=>repo.reviewPackageCAS("package",{reviewer_role:"writer",decision:"approve",expected_revision:3}),/package_revision_conflict/)});
test("workspace review actions follow the server capability, materialize Drive artifacts, and fence revisions",async()=>{const html=await(await worker.fetch(new Request("https://app.test/"),{})).text();assert.match(html,/data-revision=/);assert.match(html,/expected_revision:Number\(form\.dataset\.revision\)/);assert.match(html,/reviewCapability = pkg\.review_capability/);assert.match(html,/reviewer_role:capability\.reviewer_role/);assert.match(html,/data-materialize-drive=/);assert.match(html,/materialize-drive/);assert.match(html,/state\.selectionGeneration !== generation/);assert.doesNotMatch(html,/\['target','considering','package_draft','chris_review','approved_to_send','applied'/)});
test("manual applied stage is rejected until a verified submission receipt exists",async()=>{const repo=createMemoryRepo();repo.state.jobs.set("job",{id:"job"});await assert.rejects(()=>repo.savePipeline("job",{stage:"applied"}),/verified_submission_receipt_required/)});
test("D1 intake assigns each observation to its active task in the commit batch",async()=>{let batch=[];const db={prepare(sql){return{bind(...args){return{sql,args,run:async()=>({})}}}},async batch(statements){batch=statements}};await new D1Repository(db).atomicCommitMessage({message:{id:"m",source:"indeed",html:"",is_job_newsletter:true},observation:{links:[{kind:"listing",source:"indeed",url:"https://indeed.com/viewjob?jk=1"}]},tasks:[{id:"research_1",observation_ordinal:0,source:"indeed",task_kind:"fetch_listing",url:"https://indeed.com/viewjob?jk=1",status:"pending"}]});assert.ok(batch.some(x=>x.sql.includes("active_research_task_assignments")))});
test("freshness ignores unverified dashboard uploads",async()=>{const sqls=[],db={prepare(sql){sqls.push(sql);return{bind(){return{first:async()=>null}}}}};await assert.rejects(()=>new D1Repository(db).assertListingFresh("job","approval"),/trusted_fresh_listing_check_required/);assert.ok(sqls.some(x=>x.includes("capture_source='public_server_fetch'")))});

